param([string]$OutputRoot='')
$ErrorActionPreference='Stop';$expected='26H1';$repo=(Resolve-Path (Join-Path $PSScriptRoot '../../../..')).Path
Write-Host '';Write-Host 'WINDOWS WORKLOAD PROTECTION RESEARCH';Write-Host '====================================';Write-Host '';Write-Host 'This collection is READ-ONLY.';Write-Host 'No Windows Update settings will be changed.';Write-Host 'No restart will be initiated.';Write-Host 'No files will be modified outside the results directory.';Write-Host ''
$os=Get-CimInstance Win32_OperatingSystem;$cv=Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion';if($os.Caption -notmatch 'Windows 11'){throw "Not Windows 11: $($os.Caption)"};if([string]$cv.DisplayVersion -ne $expected){throw "Expected Windows 11 $expected; detected '$($cv.DisplayVersion)' build $($os.BuildNumber)."}
if(!$OutputRoot){$OutputRoot=Join-Path $repo 'experiments\results'}elseif(!(Split-Path $OutputRoot -IsAbsolute)){$OutputRoot=Join-Path (Get-Location) $OutputRoot};$dir=Join-Path $OutputRoot ("windows-11-{0}\{1}\{2}" -f $expected,$env:COMPUTERNAME,(Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH-mm-ssZ'));New-Item -ItemType Directory -Path $dir -Force|Out-Null;$common=Join-Path $repo 'experiments\commands\common'
$steps=@(@('Windows version','system-info.ps1','system.json'),@('Process information','process-info.ps1','processes.json'),@('Windows Update state','update-state.ps1','windows-update.json'),@('Update Orchestrator events','event-log.ps1','update-events.json'),@('Restart policy state','policy-state.ps1','policies.json'));$records=@();$i=0
foreach($s in $steps){$i++;Write-Host (" [{0}/5] {1} " -f $i,$s[0]) -NoNewline;try{& (Join-Path $common $s[1]) -OutputFile (Join-Path $dir $s[2]);Write-Host '.... OK';$records+=[ordered]@{name=$s[0];status='OK';output=$s[2]}}catch{Write-Host '.... FAILED';$records+=[ordered]@{name=$s[0];status='FAILED';error=$_.Exception.Message;output=$s[2]}}}
[ordered]@{collector_version='0.1.0';expected_release=$expected;collected_utc=(Get-Date).ToUniversalTime().ToString('o');computer_name=$env:COMPUTERNAME;windows_build=$os.BuildNumber;result_directory=$dir;steps=$records}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $dir 'collection.json') -Encoding UTF8
Write-Host '';Write-Host 'Results written to:';Write-Host $dir
